@if($product)<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('onboarding-wizard'),steps=[...form.querySelectorAll('.wizard-step')],dots=[...document.querySelectorAll('.wizard-dot')],back=document.getElementById('wizard-back'),next=document.getElementById('wizard-next'),submit=document.getElementById('wizard-submit'),locations=JSON.parse(document.getElementById('tanzania-locations').textContent),region=document.getElementById('region'),district=document.getElementById('district'),ward=document.getElementById('ward');const fill=(select,items,placeholder,selected='')=>{select.innerHTML='<option value="">'+placeholder+'</option>';items.forEach(item=>select.add(new Option(item,item,false,item===selected)));select.disabled=!items.length};fill(region,Object.keys(locations),'Select region',region.dataset.old);const loadDistricts=selected=>fill(district,Object.keys(locations[region.value]||{}),'Select district',selected);const loadWards=selected=>fill(ward,(locations[region.value]||{})[district.value]||[],'Select ward',selected);region.addEventListener('change',()=>{loadDistricts('');fill(ward,[],'Select ward')});district.addEventListener('change',()=>loadWards(''));if(region.value){loadDistricts(district.dataset.old);if(district.value)loadWards(ward.dataset.old)}let current=0;const show=i=>{current=i;steps.forEach((s,n)=>s.classList.toggle('active',n===i));dots.forEach((d,n)=>{d.classList.toggle('active',n===i);d.classList.toggle('done',n<i)});back.hidden=i===0;next.hidden=i===steps.length-1;submit.hidden=i!==steps.length-1;steps[i].querySelector('input,select,textarea')?.focus()};const valid=()=>{for(const el of steps[current].querySelectorAll('input,select,textarea'))if(!el.checkValidity()){el.reportValidity();return false}return true};next.addEventListener('click',()=>{if(valid())show(current+1)});back.addEventListener('click',()=>show(current-1));dots.forEach((d,i)=>d.addEventListener('click',()=>{if(i<current||valid())show(i)}));show(0);});</script>@endif
@if($product)<script>document.addEventListener('DOMContentLoaded',()=>{const wizardSteps=[...document.querySelectorAll('.wizard-step')];wizardSteps.forEach((step,index)=>{const label=step.querySelector('.eyebrow');if(label)label.textContent='STEP '+(index+1)+' OF '+wizardSteps.length})});</script>@endif
@if($product)<script>document.addEventListener('DOMContentLoaded',()=>{const customer=JSON.parse(document.getElementById('assigned-customer').textContent),products=JSON.parse(document.getElementById('onboarding-products').textContent),product=document.getElementById('product-id'),form=document.getElementById('onboarding-wizard');const set=(name,value)=>{const field=form.elements[name];if(field)field.value=value??''};if(customer){['name','email','phone','alternative_phone','gender','address','occupation','next_of_kin','next_of_kin_phone'].forEach(name=>set(name,customer[name]));set('date_of_birth',(customer.date_of_birth||'').slice(0,10));set('region',customer.region);document.getElementById('region').dispatchEvent(new Event('change'));setTimeout(()=>{set('district',customer.district);document.getElementById('district').dispatchEvent(new Event('change'));setTimeout(()=>set('ward',customer.ward),0)},0)}const updateProduct=()=>{const selected=products.find(item=>String(item.id)===product.value);if(!selected)return;set('device_price',selected.value);set('upfront_amount',selected.upfront);const review=form.querySelector('.review-grid');if(review)review.innerHTML='<div><small>Product</small><strong>'+selected.name+'</strong></div><div><small>Category</small><strong>'+selected.category+'</strong></div><div><small>Financing value</small><strong>'+Number(selected.value).toLocaleString()+' TZS</strong></div><div><small>Total upfront payable</small><strong>'+Number(selected.upfront).toLocaleString()+' TZS</strong></div><div><small>Total repayable</small><strong>'+Number(selected.repayment_total).toLocaleString()+' TZS</strong></div><div><small>Maximum loans</small><strong>'+selected.max_loans+'</strong></div>'};product.addEventListener('change',updateProduct);updateProduct()});</script>@endif
@if($product)<script>document.addEventListener('DOMContentLoaded',()=>{const customer=JSON.parse(document.getElementById('assigned-customer').textContent),products=JSON.parse(document.getElementById('onboarding-products').textContent),select=document.getElementById('product-id'),amount=document.getElementById('device-price'),help=document.getElementById('amount-help'),form=document.getElementById('onboarding-wizard');if(customer){form.elements.first_name.value=customer.first_name||customer.name?.split(' ')[0]||'';form.elements.middle_name.value=customer.middle_name||'';form.elements.last_name.value=customer.last_name||customer.name?.split(' ').slice(-1)[0]||''}const configure=()=>{const p=products.find(item=>String(item.id)===select.value);if(!p)return;if(p.category==='submeter'){amount.value=p.value;amount.readOnly=true;amount.min=p.value;amount.max=p.value;help.textContent='Fixed submeter financing amount.'}else{amount.readOnly=false;amount.min=2000;amount.max=customer?.token_qualifying_amount||5000;if(Number(amount.value)<2000||Number(amount.value)>Number(amount.max))amount.value=Math.min(p.value,Number(amount.max));help.textContent='Enter 2,000 to '+Number(amount.max).toLocaleString()+' TZS.'}};select.addEventListener('change',configure);configure()});</script>@endif
@if($product)<script>document.addEventListener('DOMContentLoaded',()=>{const products=JSON.parse(document.getElementById('onboarding-products').textContent),customer=JSON.parse(document.getElementById('assigned-customer').textContent),select=document.getElementById('product-id'),fields=[...document.querySelectorAll('.submeter-field')],form=document.getElementById('onboarding-wizard');if(customer){form.elements.id_type.value=customer.id_type||'national_id';form.elements.id_number.value=customer.id_number||''}const toggle=()=>{const selected=products.find(p=>String(p.id)===select.value),show=selected?.category==='submeter';fields.forEach(wrapper=>{wrapper.hidden=!show;const input=wrapper.querySelector('input');input.required=show;if(!show)input.value=''})};select.addEventListener('change',toggle);toggle()});</script>@endif
@if($product)<script>document.addEventListener('DOMContentLoaded',()=>{const products=JSON.parse(document.getElementById('onboarding-products').textContent),select=document.getElementById('product-id'),form=document.getElementById('onboarding-wizard'),upfrontStep=form.querySelector('[data-step="5"]'),upfrontDot=document.querySelector('[data-step-target="5"]'),next=document.getElementById('wizard-next'),submit=document.getElementById('wizard-submit');const configureUpfront=()=>{const selected=products.find(p=>String(p.id)===select.value),token=selected?.category==='token';upfrontStep.hidden=token;upfrontDot.hidden=token;upfrontStep.querySelectorAll('input,select,textarea').forEach(field=>field.disabled=token);if(form.querySelector('[data-step="4"]').classList.contains('active')){next.hidden=token;submit.hidden=!token}};select.addEventListener('change',configureUpfront);document.querySelector('[data-step-target="4"]').addEventListener('click',()=>setTimeout(configureUpfront));document.getElementById('wizard-back').addEventListener('click',()=>setTimeout(configureUpfront));next.addEventListener('click',()=>setTimeout(configureUpfront));configureUpfront()});</script>@endif
